                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objs.append((color, cells))

    out = [[0] * w for _ in range(h)]
    # Treat components as movable pieces. Pack them against the bottom,
    # selecting placements that keep them as close as possible to their
    # original horizontal position.
    objs.sort(key=lambda o: max(r for r, c in o[1]), reverse=True)
    for color, cells in objs:
        r0 = min(r for r, c in cells)
        c0 = min(c for r, c in cells)
        shape = [(r-r0, c-c0) for r, c in cells]
        bh = max(r for r, c in shape) + 1
        bw = max(c for r, c in shape) + 1
        best = None
        for top in range(h-bh, -1, -1):
            for left in range(w-bw+1):
                if all(out[top+dy][left+dx] == 0 for dy, dx in shape):
                    score = (top, abs(left-c0))
                    if best is None or score > best[0]:
                        best = (score, top, left)
        if best:
